style.css:
@-moz-document domain("bandlab.com") {
body {
    background: url("https://i.pinimg.com/736x/d3/6e/97/d36e976e3993cb803f44bf6da99475e9.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Optional: hide or override default BandLab backgrounds */
  .bl-background,
  .background-container,
  [class*="background"],
  [style*="background"] {
    background: none !important;
  }
}
